  var enhancedFindings=items.length?items.map(function(item,index){var th=reportThemePro(clientSectionName(item.section||""));var level=index<2?"High impact":index<4?"Medium impact":"Supporting fix";return '<article class="pdf-pro-finding '+th.tone+'"><div style="text-transform:none"><b>'+String(index+1).padStart(2,"0")+'</b><span>'+level+' · '+esc(clientSectionName(item.section||"Priority"))+'</span></div><h3>'+esc(item.name)+'</h3><p><strong>Business effect</strong><br>'+esc(item.impact)+'</p><aside><span>Recommended next step</span><strong>'+esc(item.action)+'</strong></aside></article>'}).join(""):'<div class="pdf-pro-empty"><strong>Complete the remaining checks before sending the final report.</strong></div>';
