/* Keep the exported cover intentionally minimal: title plus date only. */
var reportPrintProposalBase=printProposal;
printProposal=function(lead){
  var nativeOpen=window.open;
  window.open=function(){
    var popup=nativeOpen.apply(window,arguments);
    if(popup&&popup.document){
      var nativeWrite=popup.document.write.bind(popup.document);
      popup.document.write=function(html){
        html=html.replace(/<title>.*?<\/title>/,'<title>Google Business Profile Audit</title>');
        html=html.replace(/<span class="pdf-mark">.*?<\/span>/,'<span class="pdf-mark">'+reportIconPro("compass")+' Google Business Profile Audit</span>');
        html=html.replace('<span class="pdf-cover-label">Client Report</span>','');
        html=html.replace('<small>Google Business Profile Review</small>','');
        html=html.replace(/<div class="pdf-cover-footer"><span>Prepared by.*?<\/span>/,'<div class="pdf-cover-footer"><span></span>');
        nativeWrite(html);
      };
    }
    return popup;
  };
  try{return reportPrintProposalBase(lead)}finally{window.open=nativeOpen}
};
